#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 14d: Operations and Security in the admin dashboard
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check it, then fast forward main.
#
# After this part, Operations and Security in the dashboard are live:
#   Operations
#   * Processing jobs: Failed, Waiting, Running, Recent, each step by name
#     with its video and owner; Run again (refused when a retry cannot help)
#   * Unfinished uploads: every one, with its owner; Discard
#   * Shelby stores: the ones not confirmed; Check now
#   * Housekeeping: run the hourly sweep now
#   Security
#   * suspended wallets, wallets signed in, dashboard sessions (this browser
#     marked) with "Sign out every other session"
#   * dashboard sign in activity
#   * refused wallet sign ins and rate limits reached, kept in the server's
#     memory only; callers shown as codes that change on restart, never IPs
#   * each action is written to the audit log
#
#   BACKEND    2 new files, 3 changed. No migration
#   DASHBOARD  2 new files, 3 changed. No packages
#
#   ./vm_ops.sh            apply (needs Part 14c on the branch)
#   ./vm_ops.sh --force    apply even if local files differ from GitHub
#   ./vm_ops.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_ops"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_ops_backups"

ADD=(
  "backend/src/lib/adminOps.ts"
  "backend/src/lib/securityLog.ts"
  "dashboard/src/app/(admin)/operations/page.tsx"
  "dashboard/src/app/(admin)/security/page.tsx"
)
MOD=(
  "backend/src/routes/admin.ts"
  "backend/src/lib/guard.ts"
  "backend/src/routes/auth.ts"
  "dashboard/src/lib/api.ts"
  "dashboard/src/components/Shell.tsx"
  "dashboard/src/app/(admin)/page.tsx"
)
PRE_MOD=(
  "05db9acbe0474dfc2abfc31e5306496e3b997c53445b1529db6136e526a08ff2"
  "bba7fbe0994b6ec8a88ae7c08d8220bd4fbf91488a84a9ac2ba608afae2262f3"
  "fed4541a6cfe09d9b0e5df9ff129219e8801a738d8d2544fb15b8d1042b24373"
  "a96e60e5b598fe7269eb5a54bc49cedd6b620ed2a0dc56fea4875fa8aaf8a1c3"
  "8a6c8c4c046749e6cbe0e1ca2c8532abeeadc6304cbe487a5e4a7c25140083f3"
  "6ad6972226b2435908900a6cf104fe234acde7160391bcfdc4afeb17716743a8"
)
NEW_MOD=(
  "9e804d6432182b710d88c4603468964ea0612287df576ac7868d1978346c3cc9"
  "ab77fdf7ad2c11f1e5970600e3510917e884c6b4d6f067c32e907795e3234eca"
  "f564f436e24b2c615f695564b50ab62eba5d897780b0ada0007aacf23c3b9f51"
  "2e8819b999a5d2eab057f4023e324f98dbc31639ca3f114f86bec2c7945f447c"
  "f174f8696921076b270ed5465bb18b535cefa62cd321ef1288911d452d250a01"
  "18e0eb80c19522ecb0487a3ce6b0aa7b3a2992d36d7c9214a0699b34378f4f0e"
)
NEW_ADD=(
  "f645ad80b6ed95da7514679462832b049997c5512392a1cbde7d24ccc73a5a07"
  "3c5fff6743ea181b3bbc48203d211a76d6cd52e6cb5133a25c452d054ed3281f"
  "c0d58237a8fe7f9809a34ec442522ac0b4547826f6fdf666430589a0acfedbb9"
  "1cb51df6cf1ee8705522ede75fafb0a3f2b6d1161e7d7e2c7e51f222189abddb"
)

say() { printf '  %s\n' "$1"; }
die() { printf 'ERROR: %s\n' "$1" >&2; exit 1; }
sha() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1
  else shasum -a 256 "$1" | cut -d' ' -f1; fi
}
bname() { printf '%s' "$1" | sed 's#/#__#g'; }

[ -d frontend ] && [ -d backend ] || die "Run from repo root (dir with backend/ and frontend/)."

BRANCH="$(git rev-parse --abbrev-ref HEAD 2>/dev/null || true)"
if [ "$BRANCH" = "main" ]; then
  die "You are on main. This part is for the rebuild branch. Run: git checkout rebuild"
fi

restore_from() {
  local f
  for f in "${MOD[@]}"; do
    if [ -f "$1/$(bname "$f")" ]; then mkdir -p "$(dirname "$f")"; cp "$1/$(bname "$f")" "$f"; fi
  done
  for f in "${ADD[@]}"; do
    if [ -f "$1/$(bname "$f")" ]; then cp "$1/$(bname "$f")" "$f"; else rm -f "$f"; fi
  done
  # Folders this part made, once empty, go too.
  for f in "${ADD[@]}"; do
    d="$(dirname "$f")"
    while [ "$d" != "." ] && [ "$d" != "/" ] && rmdir "$d" 2>/dev/null; do d="$(dirname "$d")"; done
  done
}

if [ "${1:-}" = "--revert" ]; then
  [ -d "$BAKDIR" ] || die "No backup dir. Nothing to revert."
  LATEST="$(ls -1d "$BAKDIR"/*/ 2>/dev/null | sort | tail -1)"
  [ -n "$LATEST" ] || die "No backups found."
  restore_from "${LATEST%/}"
  say "Restored 6 changed files and removed 4 new files, from $LATEST"
  exit 0
fi

FORCE=0
[ "${1:-}" = "--force" ] && FORCE=1

if [ -f "${ADD[0]}" ] && grep -q "$MARKER" "${ADD[0]}" && grep -q "adminOps" "backend/src/routes/admin.ts"; then
  say "Already applied ($MARKER marker present). Use --revert to undo."
  exit 0
fi

grep -q "adminContent" backend/src/routes/admin.ts 2>/dev/null || die "Part 14c is not on this branch. Run: git pull origin rebuild"

# ---- pre image check: every file must match what this part was built on ----
check_pre() {
  [ -f "$1" ] || die "$1 not found. Nothing changed."
  if [ "$(sha "$1")" != "$2" ]; then
    if [ "$FORCE" = "1" ]; then say "WARNING: $1 differs from GitHub rebuild (f0cb3e0). Proceeding (--force)."
    else die "$1 differs from the version this part was built on (GitHub rebuild (f0cb3e0)). Nothing changed. Run git pull origin rebuild, push or stash local edits, or run again with --force."; fi
  fi
}
i=0; for f in "${MOD[@]}"; do check_pre "$f" "${PRE_MOD[$i]}"; i=$((i+1)); done
i=0; for f in "${ADD[@]}"; do
  # A file already there with exactly this part's content is fine.
  if [ -f "$f" ] && [ "$FORCE" != "1" ] && [ "$(sha "$f")" != "${NEW_ADD[$i]}" ]; then die "$f already exists but is not this part's version. Nothing changed. Run again with --force to overwrite it."; fi
  i=$((i+1))
done

# ---- decode + verify every payload BEFORE touching anything ----
TMPD="$(mktemp -d)"
trap 'rm -rf "$TMPD"' EXIT
verify() {
  [ -s "$1" ] || die "$3: base64 decode produced an empty file. Nothing written."
  [ "$(sha "$1")" = "$2" ] || die "$3: payload checksum mismatch (script was corrupted in transit). Nothing written."
}

