verify "$TMPD/a3" "${NEW_ADD[3]}" "dashboard/src/app/(admin)/security/page.tsx"

grep -q "$MARKER" "$TMPD/a0"                                   || die "adminOps.ts payload missing marker. Aborting."
grep -q 'export async function retryJobById' "$TMPD/a0"          || die "adminOps.ts payload is wrong. Aborting."
grep -q 'export function recordLimitHit' "$TMPD/a1"              || die "securityLog.ts payload is wrong. Aborting."
grep -q 'Run the housekeeping now' "$TMPD/a2"                    || die "operations page payload is wrong. Aborting."
grep -q 'Sign out every other session' "$TMPD/a3"                || die "security page payload is wrong. Aborting."
grep -q 'adminOps' "$TMPD/m0"                        || die "routes/admin.ts payload is wrong. Aborting."
grep -q 'adminContent' "$TMPD/m0"                    || die "routes/admin.ts payload lost 14c. Aborting."
grep -q 'recordLimitHit' "$TMPD/m1"                     || die "guard.ts payload is wrong. Aborting."
grep -q 'recordRefusedSignIn' "$TMPD/m2"              || die "routes/auth.ts payload is wrong. Aborting."
grep -q 'SUSPENDED_MESSAGE' "$TMPD/m2"                || die "routes/auth.ts payload lost 14b. Aborting."
grep -q 'export const getSecurity' "$TMPD/m3"           || die "dashboard api.ts payload is wrong. Aborting."
grep -q 'href: "/operations"' "$TMPD/m4"      || die "Shell.tsx payload is wrong. Aborting."
say "10 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Operations and Security (Part 14d)."
say "No migration and nothing to install."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit && npm run build) && (cd frontend && npx tsc --noEmit && npm run build)"
say "  (cd dashboard && npm install && npx tsc --noEmit && npm run build)"
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_ops.sh --revert"
